result:
.pageOn{
    border-radius 6px!important
}
.news-box{
	.list{
		padding: 0 12px 16px 12px;
		.title{
			color: #999999;
			font-size: 12px;
			padding: 16px 0;

			.top{
				font-size: 16px;
			}

			.pictrue{
				height: 18px;
				img {
					height: 100%;
					width: 100%;
				}
			}
			.iconfont{
				font-size: 12px;
			}
		}
		.text{
			color: #282828;
			font-size: 14px;

			.num{
				font-size: 15px;
				margin-right: 7px;
				color: #999999;
				&.on{
					color: #E93323;
				}
				&.on2{
					color: #FF7300;
				}
				&.on3{
					color: #FFC300;
				}
			}

			&~.text{
				margin-top: 12px;
			}
		}
	}
	.item{
		   display flex
		   align-items center
		   height 44px
		   padding: 0 10px;
		   font-size: 13px;
		   color: #333;
		   position: relative;
		   .top{
			   max-width: 64px;
			   height: 20px;
			   font-size: 13px;
			   text-align: center
			   line-height: 20px;
			   padding: 0 6px;
			   border-radius: 4px;
			   margin-right: 8px;
		   }
		   .iconfont {
			   color: #999;
			   font-size: 14px;
		   }
		   .img-box{
		   	height 24px
		   	img {
		   		height 100%
				margin-right: 8px;
		   	}
		   }
		   .right-box{
		   	flex 1
		   	overflow: hidden;
		   	text-overflow:ellipsis;
		   	white-space: nowrap;
		   }
	}
}
